import {curve,grams,validDrink,HOUR} from './model.js';
const $=id=>document.getElementById(id),KEY='next-morning-v1';
const presets=[['A. Le Coq Premium',500,4.7,'Beer'],['A. Le Coq Premium',330,4.7,'Beer'],['Saku Originaal',500,4.7,'Beer'],['Saku Originaal',330,4.7,'Beer'],['Saku Rock',568,5.3,'Beer'],['A. Le Coq Alexander',500,5.2,'Beer'],['A. Le Coq Alexander',330,5.2,'Beer'],['A. Le Coq Alexander',568,5.2,'Beer'],['A. Le Coq Special',500,5.2,'Beer'],['Fizz Pear cider',500,4.5,'Cider'],['Fizz Blueberry cider',500,4.5,'Cider'],['Fizz Original Dry cider',330,4.7,'Cider'],['A. Le Coq Long Tropical',330,5.5,'Long drinks'],['A. Le Coq Long Grapefruit',330,5.5,'Long drinks'],['A. Le Coq Long Grapefruit',500,5.5,'Long drinks'],['A. Le Coq I',500,2.9,'Beer'],['A. Le Coq Pilsner',500,4.2,'Beer'],['Somersby Pear',330,4.5,'Cider'],['Somersby Apple',330,4.5,'Cider'],['Antvärk Paljas Õun',330,4.5,'Cider'],['Hoggy’s Gin & Herbs',500,5,'Long drinks'],['Fizz Pear cider',1500,4.5,'Cider'],['Fizz Blueberry cider',1500,4.5,'Cider'],['Saku Karl Friedrich',330,5,'Beer'],['Saku Karl Friedrich',500,5,'Beer'],['Saku Karl Friedrich',568,5,'Beer'],['Saku Karl Friedrich Märzen',568,5,'Beer'],['Saku Karl Friedrich Tšehhi Lager',568,5,'Beer'],['A. Le Coq Premium Select',355,4.3,'Beer'],['A. Le Coq Special',330,5.2,'Beer'],['Custom drink',330,0,'Other']];
const blank=()=>({weight:'',r:'',started:'',drinks:[]});let state=blank(),editing=null,storageOK=true;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.drinks)){state={weight:s.weight>=35&&s.weight<=300?s.weight:'',r:[0.68,0.55].includes(+s.r)?+s.r:'',started:typeof s.started==='string'?s.started:'',drinks:s.drinks.filter(d=>validDrink(d)&&typeof d.id==='string')};}}catch{storageOK=false;}
const local=t=>{const d=new Date(t);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const time=t=>new Date(t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false});
const date=t=>new Date(t).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});
const rounded=t=>Math.ceil(t/(15*60000))*15*60000;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('storage-status').textContent=storageOK?'Saved only in this browser · No account, cookies or analytics':'Browser storage unavailable · Changes last only for this visit';}
function syncProfile(){$('weight').value=state.weight;$('sex').value=state.r;$('started').value=state.started;updateProfile();}
presets.sort((a,b)=>{if(a[3]==='Other')return 1;if(b[3]==='Other')return -1;const order=['Beer','Cider','Long drinks'];return order.indexOf(a[3])-order.indexOf(b[3])||a[0].localeCompare(b[0],'et')||a[1]-b[1];});
const groups=new Map();presets.forEach((p,i)=>{if(!groups.has(p[3])){const group=document.createElement('optgroup');group.label=p[3];groups.set(p[3],group);$('preset').append(group);}const o=document.createElement('option');o.value=i;o.textContent=i===presets.length-1?p[0]:p[0]+' · '+p[1]+' ml · '+p[2]+'%';groups.get(p[3]).append(o);});
function updateFields(){const custom=+$('preset').value===presets.length-1;$('custom-fields').hidden=!custom;$('custom-fields').disabled=!custom;const p=presets[+$('preset').value];$('preset-info').textContent=custom?'Enter the amount you actually finished.':'One full '+p[1]+' ml bottle or can · '+p[2]+'% ABV. Check your label.';}
function selectPreset(){const p=presets[+$('preset').value];$('name').value=p[0];$('volume').value=p[1];$('abv').value=p[2];updateFields();}
function updateTime(){$('finished-label').hidden=!$('backdate').checked;$('finished').disabled=!$('backdate').checked;}
$('backdate').onchange=()=>{if($('backdate').checked)$('finished').value=local(Date.now());updateTime();};
$('preset').onchange=selectPreset;selectPreset();$('finished').value=local(Date.now());
function updateProfile(){$('profile').open=!profileValid();$('profile-summary').textContent=profileValid()?state.weight+' kg · '+(+state.r===.68?'Male':'Female')+' · Edit':'Set weight and sex';}
function profileValid(){return state.weight>=35&&state.weight<=300&&[0.68,0.55].includes(+state.r);}
['weight','sex','started'].forEach(id=>$(id).addEventListener('change',()=>{state.weight=$('weight').value;state.r=+$('sex').value;state.started=$('started').value;save();updateProfile();render();}));
function resetForm(){editing=null;$('add').textContent='+ Add drink';$('cancel-edit').hidden=true;$('finished').value=local(Date.now());$('error').textContent='';$('backdate').checked=false;$('advanced').open=false;updateTime();updateFields();}
$('cancel-edit').onclick=resetForm;
$('drink-form').onsubmit=e=>{e.preventDefault();$('error').textContent='';if(!profileValid()){$('error').textContent='Enter a weight from 35–300 kg and select the model’s sex factor.';$('profile').open=true;$('weight').focus();return;}const d={id:editing??crypto.randomUUID(),name:$('name').value.trim(),volume:+$('volume').value,abv:+$('abv').value,time:$('backdate').checked?new Date($('finished').value).getTime():Date.now()};if(!validDrink(d)){$('error').textContent='Check the name, amount, ABV and date. Finished drinks must be within the past 7 days, not in the future.';return;}if(state.started&&(!Number.isFinite(new Date(state.started).getTime())||new Date(state.started).getTime()>Math.min(d.time,...state.drinks.filter(x=>x.id!==editing).map(x=>x.time)))){$('error').textContent='The optional start time must be before all finished drinks. Update or clear it.';return;}if(editing)state.drinks=state.drinks.map(x=>x.id===editing?d:x);else state.drinks.push(d);save();resetForm();render();$('status').textContent='Drink saved. Estimate updated.';$('add-status').textContent=d.name+' added at '+time(d.time)+'.';};
function renderDiary(){const list=$('drink-list');list.replaceChildren();$('total').textContent=`${state.drinks.length} drink${state.drinks.length===1?'':'s'} · ${state.drinks.reduce((n,d)=>n+grams(d),0).toFixed(1)} g alcohol`;if(!state.drinks.length){const p=document.createElement('p');p.className='empty';p.textContent='No drinks logged. Your evening starts here.';list.append(p);return;}[...state.drinks].sort((a,b)=>a.time-b.time).forEach((d,i)=>{const row=document.createElement('div');row.className='drink-row';const n=document.createElement('span');n.className='drink-num';n.textContent=String(i+1).padStart(2,'0');const info=document.createElement('div');info.className='drink-info';const title=document.createElement('strong');title.textContent=d.name;const detail=document.createElement('small');detail.textContent=`${d.volume} ml · ${d.abv}% · ${grams(d).toFixed(1)} g · ${date(d.time)}`;info.append(title,detail);const actions=document.createElement('div');actions.className='row-actions';const edit=document.createElement('button');edit.textContent='Edit';edit.setAttribute('aria-label',`Edit drink ${i+1}: ${d.name}`);edit.onclick=()=>{editing=d.id;$('name').value=d.name;$('volume').value=d.volume;$('abv').value=d.abv;$('finished').value=local(d.time);$('preset').value=presets.length-1;$('add').textContent='Save changes';$('cancel-edit').hidden=false;$('backdate').checked=true;$('advanced').open=true;updateTime();updateFields();$('name').focus();};const del=document.createElement('button');del.textContent='Remove';del.setAttribute('aria-label',`Remove drink ${i+1}: ${d.name}`);del.onclick=()=>{state.drinks=state.drinks.filter(x=>x.id!==d.id);if(editing===d.id)resetForm();save();render();};actions.append(edit,del);row.append(n,info,actions);list.append(row);});}
function renderChart(curves,now){const start=Math.min(curves[0].points[0].t,now-HOUR/2),end=Math.max(now+HOUR,...curves.map(c=>c.zero??now))+HOUR/2;const max=Math.max(.4,...curves.flatMap(c=>c.points.map(p=>p.b)))*1.15;const x=t=>52+(t-start)/(end-start)*588,y=b=>214-b/max*175;const path=c=>[...c.points,{t:end,b:0}].map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(2)},${y(p.b).toFixed(2)}`).join(' ');let svg='<svg viewBox="0 0 670 255" role="img" aria-labelledby="chart-title"><title id="chart-title">Estimated BAC over time. Central, faster and slower elimination scenarios; not measured BAC.</title>';
for(let i=0;i<5;i++){const b=max*i/4;svg+=`<line x1="52" x2="640" y1="${y(b)}" y2="${y(b)}" stroke="#35505f"/><text x="40" y="${y(b)+4}" text-anchor="end" fill="#abc3d0" font-size="12">${b.toFixed(1)}</text>`;}
for(let i=0;i<5;i++){const t=start+(end-start)*i/4;svg+=`<text x="${x(t)}" y="242" text-anchor="middle" fill="#abc3d0" font-size="12">${time(t)}</text>`;}
curves.forEach((c,i)=>svg+=`<path d="${path(c)}" fill="none" stroke="${i===0?'#80e3e0':'#568899'}" stroke-width="${i===0?3:1.5}" ${i?'stroke-dasharray="5 5"':''}/>`);
svg+=`<line x1="${x(now)}" x2="${x(now)}" y1="20" y2="215" stroke="#b8d0da" stroke-dasharray="3 5"/><text x="${Math.min(600,Math.max(70,x(now)))}" y="14" text-anchor="middle" fill="#dce9ee" font-size="12">NOW</text><circle cx="${x(now)}" cy="${y(curves[0].current)}" r="5" fill="#80e3e0"/></svg>`;$('chart').innerHTML=svg;}
function render(){renderDiary();const now=Date.now();$('clock').textContent=`${time(now)} · local time`;if(!profileValid()||!state.drinks.length){$('bac').textContent='—';$('zero').textContent=profileValid()?'Add your first drink':'Set up your profile';$('zero-sub').textContent='No estimate until a drink is logged.';$('range-note').textContent='The graph updates whenever you add or edit a drink.';$('chart').innerHTML='<div class="chart-empty"><strong>A clearer view of your evening</strong><span>Select your drink and tap Add drink.</span></div>';return;}const curves=[.15,.2,.1].map(b=>curve(state.drinks,+state.weight,+state.r,b,now));const central=curves[0];$('bac').textContent=central.current>0&&central.current<.01?'<0.01':central.current.toFixed(2);$('zero').textContent=central.zero?`~ ${date(rounded(central.zero))}`:'No alcohol logged';$('zero-sub').textContent=central.zero&&central.zero<=now?'Model zero has passed. This is not driving clearance.':'Central assumption · rounded to 15 minutes';$('range-note').textContent=central.zero?`Model zero scenarios: ${date(rounded(curves[1].zero))} – ${date(rounded(curves[2].zero))}. Real clearance may be later.`:'Only zero-ABV drinks are logged. This does not establish your actual BAC.';renderChart(curves,now);}
$('clear').onclick=()=>{if(!confirm('Delete your saved profile and all drinks from this browser?'))return;state=blank();try{localStorage.removeItem(KEY);}catch{}resetForm();syncProfile();render();$('status').textContent='Your local diary and profile have been deleted.';};
syncProfile();render();if(!storageOK)$('storage-status').textContent='Browser storage unavailable or unreadable · Changes may not persist';setInterval(()=>{render();if(!editing&&!$('backdate').checked&&document.activeElement!==$('finished'))$('finished').value=local(Date.now());},60000);
try{if(document.modelContext?.registerTool)Promise.resolve(document.modelContext.registerTool({name:'read_alcohol_diary',description:'Read the visible drink diary and model assumptions. Estimates never establish fitness to drive.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected empty input');return {profile:{weight:state.weight,r:state.r},drinks:structuredClone(state.drinks),warning:'Educational model only. Never driving clearance.'};}})).catch(()=>{});}catch{}

function setTheme(theme){document.documentElement.dataset.theme=theme;$('theme').textContent=theme==='dark'?'Light mode':'Dark mode';$('theme').setAttribute('aria-label','Switch to '+(theme==='dark'?'light':'dark')+' theme');}
try{setTheme(localStorage.getItem('next-morning-theme')==='light'?'light':'dark');}catch{setTheme('dark');}
$('theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(theme);try{localStorage.setItem('next-morning-theme',theme);}catch{}};
